/** UI element ids in scope for `platform` (what its coverage test must find instrumented). */
export function uiElementsForPlatform(platform: Platform): UiElementId[] {
  return (Object.keys(UI_ELEMENTS) as UiElementId[]).filter((id) => UI_ELEMENTS[id].platforms.includes(platform));
}

/** The only allowed `telemetry-exempt: <category>: <reason>` categories (see the catalog). */
export const TELEMETRY_EXEMPT_CATEGORIES = ["duplicate", "backdrop", "gesture", "continuous", "disabled"] as const;

export function isUiElementId(v: unknown): v is UiElementId {
  return typeof v === "string" && Object.prototype.hasOwnProperty.call(UI_ELEMENTS, v);
}
